-- =============================================================================
-- 552 — LE CAHIER D'EXERCICES DE TLE (partie 24)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 552 --niveau Tle --fichiers espagnol.jumelles-2 --suffixe 24 > supabase/contenu/552_exercices_tle_24.sql
--
-- 27 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   espagnol.jumelles-2     27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('32abb538-78d2-511e-9fae-003909c02489'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les projets du week-end","competence":"comprendre-langue","situation":"Lucía et Jorge parlent de leur week-end. Lucía a un grand programme.","documents":[{"id":"planes","type":"dialogue","modele":"sms","titre":"Messages de Lucía et de Jorge","participants":[{"nom":"Lucía","emoji":"👧","cote":"gauche"},{"nom":"Jorge","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lucía","texte":"El sábado iré a la playa y haré un picnic con mis primos."},{"qui":"Jorge","texte":"Yo voy a estudiar. Pero el domingo saldré contigo."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes au futur simple**.","aide":"Ils portent tous un accent écrit sur la dernière syllabe.","type":"zone","document":"planes","multiple":true},{"enonce":"Touche la tournure qui exprime l’**intention** ou l’imminence.","aide":"Elle se compose de ir et d’une préposition, puis d’un infinitif.","type":"zone","document":"planes","multiple":true},{"enonce":"Complète avec le futur de tener.","aide":"Le futur de tener se construit sur le radical tendr-.","type":"trous","segments":["Mañana yo ",0," un examen."],"banque":["tuve","tendría","tendré","teneré"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m7","m20"]},"explication":"**Iré, haré, saldré** : trois futurs simples (haré et saldré sont irréguliers)."},{"cle":{"type":"zone","ids":["m14","m15"]},"explication":"**Voy a estudiar** : ir a + infinitif exprime l’intention, très fréquent à l’oral."},{"cle":{"type":"trous","trous":[["tendre"]]},"affichage":"tendré","explication":"**Tendré** : tener fait partie des futurs irréguliers, avec un d à la place de la voyelle."}]$ex$::jsonb),
  ('32abb538-78d2-511e-9fae-003909c02489'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La météo de demain","competence":"manier-langue","situation":"Une chaîne de télévision affiche la météo de demain pour l’Espagne. Tous les verbes sont au futur.","documents":[{"id":"tiempo","type":"fiche","modele":"affiche","entete":"El tiempo de mañana","sousTitre":"Previsión para toda España","emoji":"⛅","lignes":[{"texte":"Por la mañana lloverá en el norte.","id":"z1"},{"texte":"Por la tarde saldrá el sol en Madrid.","id":"z2"},{"texte":"Habrá viento en Galicia.","id":"z3"},{"texte":"Las temperaturas bajarán un poco.","id":"z4"}],"pied":"Previsión imaginada pour l’exercice","teinte":"bleu","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux lignes** qui contiennent un futur **irrégulier**.","aide":"Ces verbes ont un radical raccourci ou modifié : salir et haber.","type":"zone","document":"tiempo","multiple":true},{"enonce":"Associe chaque infinitif à son futur à la 1re personne.","aide":"Le e de l’infinitif tombe pour les trois premiers.","type":"association","gauche":[{"id":"g0","texte":"poder"},{"id":"g1","texte":"querer"},{"id":"g2","texte":"saber"},{"id":"g3","texte":"venir"}],"droite":[{"id":"d0","texte":"querré"},{"id":"d1","texte":"vendré"},{"id":"d2","texte":"podré"},{"id":"d3","texte":"sabré"}]},{"enonce":"Complète avec le verbe qui convient (valeur de futur).","aide":"Après cuando, avec une valeur de futur, l’espagnol évite le futur.","type":"trous","segments":["Cuando tú ",0," a casa, llámame."],"banque":["llegues","llegarás","llegara","llegaste"]},{"enonce":"Que veut dire « Habrá viento en Galicia » ?","aide":"Habrá est le futur de haber dans sa forme impersonnelle.","type":"choix","options":[{"id":"a","texte":"Il doit y avoir du vent en Galice depuis hier"},{"id":"b","texte":"Il y avait du vent en Galice"},{"id":"c","texte":"Il y aura du vent en Galice"},{"id":"d","texte":"Il y a du vent en Galice"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2","z3"]},"explication":"**Saldrá** (salir) et **habrá** (haber) : le d remplace la voyelle ; le e de l’infinitif tombe."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"*Podré, querré, sabré* : le e tombe ; *vendré* : un d remplace la voyelle."},{"cle":{"type":"trous","trous":[["llegues"]]},"affichage":"llegues","explication":"**Cuando llegues** : après cuando, on emploie le subjonctif présent, jamais le futur."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Habrá** : futur de haber, « il y aura »."}]$ex$::jsonb),
  ('32abb538-78d2-511e-9fae-003909c02489'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Marta et son avenir","competence":"argumenter","situation":"Marta écrit une lettre sur son avenir. Un tableau d’un manuel montre les futurs et les conditionnels de quatre verbes.","documents":[{"id":"marta","type":"texte","genre":"lettre","titre":"Mi futuro","blocs":["Dentro de diez años seré médica y viviré en Valencia. Cuando termine la carrera, buscaré trabajo.","No sé qué hora es: serán las nueve. Mi hermano será muy simpático, pero nunca ayuda."],"source":"Lettre écrite pour l’exercice"},{"id":"cond","type":"tableau","titre":"Futuro y condicional","colonnes":["Infinitivo","Futuro (yo)","Condicional (yo)"],"lignes":[["poder","podré","?"],["tener","tendré","?"],["hacer","haré","?"],["salir","saldré","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe au **subjonctif** : il suit « cuando » avec une valeur de futur.","aide":"Il ne porte pas la terminaison -é du futur.","type":"zone","document":"marta","multiple":false},{"enonce":"Touche le futur qui exprime une **probabilité sur le présent**.","aide":"Marta ne connaît pas l’heure exacte.","type":"zone","document":"marta","multiple":false},{"enonce":"Complète le tableau avec le conditionnel (yo).","aide":"Le conditionnel prend le même radical que le futur, avec les terminaisons -ía.","type":"trous","segments":["poder → ",0," ; tener → ",1," ; hacer → ",2," ; salir → ",3],"banque":["tendría","podría","podré","haría","haré","saldría"]},{"enonce":"Dans « Será muy simpático, pero nunca ayuda », que dit le futur ?","aide":"Le « pero » introduit une réserve.","type":"choix","options":[{"id":"a","texte":"Une concession : il est peut-être très sympathique"},{"id":"b","texte":"Une promesse sur ce qui arrivera plus tard"},{"id":"c","texte":"Un ordre donné à son frère pour demain"},{"id":"d","texte":"Une action terminée dans un passé récent"}],"multiple":false},{"enonce":"Range chaque verbe dans sa famille de futur irrégulier.","aide":"Poder donne podré, tener donne tendré, hacer donne haré.","type":"categories","categories":[{"id":"c0","texte":"Le e de l’infinitif tombe"},{"id":"c1","texte":"Un d remplace la voyelle"},{"id":"c2","texte":"Le radical est raccourci"}],"items":[{"id":"i0","texte":"saber"},{"id":"i1","texte":"poder"},{"id":"i2","texte":"decir"},{"id":"i3","texte":"salir"},{"id":"i4","texte":"hacer"},{"id":"i5","texte":"tener"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"**Termine** : après cuando, avec une valeur de futur, on emploie le subjonctif présent."},{"cle":{"type":"zone","ids":["m21"]},"explication":"**Serán las nueve** : futur de probabilité, « il doit être neuf heures »."},{"cle":{"type":"trous","trous":[["podria"],["tendria"],["haria"],["saldria"]]},"affichage":"podría · tendría · haría · saldría","explication":"**Podría, tendría, haría, saldría** : même radical que le futur, terminaisons -ía."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Será muy simpático, pero…** : futur de concession, « il est peut-être très sympathique, mais… »."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c2","i3":"c1","i4":"c2","i5":"c1"}},"explication":"*Poder, saber* : le e tombe ; *tener, salir* : un d remplace la voyelle ; *hacer, decir* : radical raccourci (haré, diré)."}]$ex$::jsonb),
  ('8c369f43-fede-5804-95de-e7c2767f7700'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le livre que lit Rosa","competence":"comprendre-langue","situation":"Une élève décrit son amie Rosa. Elle emploie un relatif dans chaque phrase.","documents":[{"id":"rosa","type":"texte","genre":"article","titre":"Mi amiga Rosa","blocs":["Mi amiga Rosa lee un libro que le gusta mucho. La chica que vino ayer es su prima.","Esta es la casa donde vivo."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux « que »** relatifs qui reprennent un nom.","aide":"Ils reprennent « libro » et « chica ».","type":"zone","document":"rosa","multiple":true},{"enonce":"Complète avec le bon relatif.","aide":"C’est le relatif général, sans préposition.","type":"trous","segments":["La película ",0," vimos ayer fue divertida."],"banque":["quien","cuyo","que","lo que"]},{"enonce":"Associe chaque relatif à ce qu’il reprend.","aide":"Un seul relatif couvre l’essentiel.","type":"association","gauche":[{"id":"g0","texte":"que"},{"id":"g1","texte":"quien"},{"id":"g2","texte":"cuyo"},{"id":"g3","texte":"lo que"}],"droite":[{"id":"d0","texte":"personnes seulement"},{"id":"d1","texte":"le « dont » de possession"},{"id":"d2","texte":"une idée entière"},{"id":"d3","texte":"personnes et choses"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m12"]},"explication":"**que** est invariable et reprend une personne ou une chose : le relatif le plus fréquent."},{"cle":{"type":"trous","trous":[["que"]]},"affichage":"que","explication":"**La película que vimos** : *que* sert de COD, sans préposition."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**que** est le cas général ; **quien** ne désigne que des personnes ; **cuyo** marque la possession ; **lo que** reprend une idée."}]$ex$::jsonb),
  ('8c369f43-fede-5804-95de-e7c2767f7700'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La personne avec qui je parle","competence":"manier-langue","situation":"Ana et Pablo parlent de la tante d’Ana et d’un cousin. Il faut placer la préposition devant le relatif.","documents":[{"id":"persona","type":"dialogue","modele":"sms","titre":"Messages d’Ana et Pablo","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Pablo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"La persona con quien hablo en el patio es mi tía."},{"qui":"Pablo","texte":"Y el chico del que me hablaste, ¿quién es?"},{"qui":"Ana","texte":"Es mi primo. Vive en la casa en la que vivimos todos."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le relatif réservé aux **personnes**.","aide":"Il suit la préposition con.","type":"zone","document":"persona","multiple":false},{"enonce":"Complète avec le bon relatif.","aide":"Une chose : que avec article. Une personne : quien.","type":"trous","segments":["La casa en la ",0," vivo es grande. El chico de ",1," te hablé vive en Cádiz."],"banque":["cuya","que","lo que","quien"]},{"enonce":"Remets en ordre : « Le garçon dont je parle vit ici. » La phrase commence par El.","aide":"La préposition ne se rejette jamais à la fin.","type":"ordre","items":[{"id":"a","texte":"hablo"},{"id":"b","texte":"vive"},{"id":"c","texte":"del que"},{"id":"d","texte":"chico"},{"id":"e","texte":"aquí"},{"id":"f","texte":"El"}]},{"enonce":"Range chaque phrase : le mot en question est-il relatif ou interrogatif ?","aide":"Un relatif reprend un nom ou un lieu ; un interrogatif pose une question.","type":"categories","categories":[{"id":"c0","texte":"Relatif (sans accent)"},{"id":"c1","texte":"Interrogatif (accent écrit)"}],"items":[{"id":"i0","texte":"Lo hizo como quiso"},{"id":"i1","texte":"¿Cuándo llegó?"},{"id":"i2","texte":"¿Cómo lo hizo?"},{"id":"i3","texte":"¿Dónde nació Lola?"},{"id":"i4","texte":"El día cuando llegó"},{"id":"i5","texte":"La ciudad donde nací"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3"]},"explication":"**quien** ne s’emploie que pour des personnes (ici après la préposition *con*)."},{"cle":{"type":"trous","trous":[["que"],["quien"]]},"affichage":"que · quien","explication":"**en la que** (une chose) et **de quien** (une personne) : la préposition précède toujours le relatif."},{"cle":{"type":"ordre","ids":["f","d","c","a","b","e"]},"explication":"**El chico del que hablo vive aquí** : *del que* devant le verbe de la relative."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c0","i5":"c0"}},"explication":"*donde, cuando, como* ne portent **jamais** d’accent comme relatifs."}]$ex$::jsonb),
  ('8c369f43-fede-5804-95de-e7c2767f7700'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Cuyo, le « dont » possessif","competence":"manier-langue","situation":"Un article de journal scolaire présente une écrivaine du quartier. Ses phrases sont pleines de « dont ».","documents":[{"id":"escritora","type":"texte","genre":"article","titre":"Una escritora famosa","blocs":["Rosalía es una escritora cuya novela leí el verano pasado.","Vive en una casa cuyos muros son blancos y recibe a muchos visitantes, lo que la cansa un poco."],"source":"Article écrit pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Pablo et Ana","participants":[{"nom":"Pablo","emoji":"👦","cote":"gauche"},{"nom":"Ana","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Pablo","texte":"¿De quién es esta casa?"},{"qui":"Ana","texte":"Es de Rosalía, la escritora."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux « dont » possessifs** du texte.","aide":"Ils s’accordent avec ce qui est possédé : novela et muros.","type":"zone","document":"escritora","multiple":true},{"enonce":"Complète avec la bonne forme de *cuyo*.","aide":"Regarde le nom qui suit chaque blanc.","type":"trous","segments":["El chico ",0," madre es médica. Los niños ",1," padres viven aquí. La casa ",2," techo es rojo."],"banque":["cuya","cuyos","cuyas","cuyo"]},{"enonce":"Quelle phrase est correcte ?","aide":"Cuyo n’est jamais suivi d’un article.","type":"choix","options":[{"id":"a","texte":"El escritor cuya novela leí es famoso."},{"id":"b","texte":"El escritor cuyo la novela leí es famoso."},{"id":"c","texte":"El escritor cuya la novela leí es famoso."},{"id":"d","texte":"El escritor cuyo novela leí es famoso."}],"multiple":false},{"enonce":"Touche les **deux mots** qui reprennent **toute l’idée** de la proposition précédente.","aide":"C’est un pronom neutre en deux mots.","type":"zone","document":"escritora","multiple":true},{"enonce":"Remets en ordre la question de Pablo : « À qui est cette maison ? » La phrase commence par ¿De.","aide":"On ne dit jamais « ¿Cuyo es? » en question.","type":"ordre","items":[{"id":"a","texte":"¿De"},{"id":"b","texte":"quién"},{"id":"c","texte":"esta casa?"},{"id":"d","texte":"es"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m14"]},"explication":"**cuya** (novela, féminin) et **cuyos** (muros, masculin pluriel) : *cuyo* s’accorde avec ce qui est possédé."},{"cle":{"type":"trous","trous":[["cuya"],["cuyos"],["cuyo"]]},"affichage":"cuya · cuyos · cuyo","explication":"**cuya madre, cuyos padres, cuyo techo** : l’accord se fait avec le nom possédé."},{"cle":{"type":"choix","ids":["a"]},"explication":"**cuya novela** : accord avec *novela* (féminin) et aucun article entre *cuyo* et le nom."},{"cle":{"type":"zone","ids":["m23","m24"]},"explication":"**lo que** reprend toute l’idée (elle reçoit beaucoup de visiteurs). On n’emploie jamais *el que* pour une phrase entière."},{"cle":{"type":"ordre","ids":["a","b","d","c"]},"explication":"**¿De quién es esta casa?** : pour demander à qui appartient quelque chose, on utilise *de quién*, jamais *cuyo*."}]$ex$::jsonb),
  ('45dce655-2ef8-5deb-b8b2-a434f37367ef'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deberes y ventana","competence":"comprendre-langue","situation":"Marta et Pablo s’écrivent avant le cours. Ils parlent des devoirs et de la fenêtre.","documents":[{"id":"ventana","type":"dialogue","modele":"sms","titre":"Mensajes de Marta y Pablo","participants":[{"nom":"Marta","emoji":"👧","cote":"gauche"},{"nom":"Pablo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marta","texte":"Hola, Pablo. ¿Estás listo para la clase?"},{"qui":"Pablo","texte":"Sí, he hecho los deberes y he escrito la redacción."},{"qui":"Marta","texte":"¿Has abierto la ventana?"},{"qui":"Pablo","texte":"No, la ventana está cerrada."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois participes irréguliers** qui suivent *haber*.","aide":"Aucun ne finit en -ado ou -ido.","type":"zone","document":"ventana","multiple":true},{"enonce":"Complète avec le participe.","aide":"Avec *haber*, le participe ne s’accorde jamais.","type":"trous","segments":["Hemos ",0," la puerta."],"banque":["abrido","abierto","abrir","abierta"]},{"enonce":"Pourquoi « cerrada » est-il féminin dans « la ventana está cerrada » ?","aide":"Avec *estar*, le participe fonctionne comme un adjectif.","type":"choix","options":[{"id":"a","texte":"Il s’accorde avec le sujet ventana"},{"id":"b","texte":"Il est toujours féminin en espagnol"},{"id":"c","texte":"Il suit l’auxiliaire haber ici"},{"id":"d","texte":"Il est invariable comme avec haber"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m14","m18"]},"explication":"**hecho, escrito, abierto** : participes irréguliers de *hacer, escribir, abrir*."},{"cle":{"type":"trous","trous":[["abierto"]]},"affichage":"abierto","explication":"**Hemos abierto** : participe irrégulier de *abrir*, invariable après *haber*."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Está cerrada** : après *ser* ou *estar*, le participe s’accorde avec le sujet."}]$ex$::jsonb),
  ('45dce655-2ef8-5deb-b8b2-a434f37367ef'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Après la vaisselle","competence":"manier-langue","situation":"Un petit mot de famille raconte ce qui s’est passé dans la cuisine, hier soir.","documents":[{"id":"cocina","type":"texte","genre":"recit","titre":"En la cocina","blocs":["Ayer mi hermano ha roto dos vasos. Mi madre ha puesto la mesa y las tazas están ya puestas. Los vasos rotos están en la basura."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux participes** qui suivent *haber* et ne s’accordent jamais.","aide":"Cherche « ha » devant le participe.","type":"zone","document":"cocina","multiple":true},{"enonce":"Touche les **deux participes** qui s’accordent avec leur nom.","aide":"Ils sont après estar ou devant un nom.","type":"zone","document":"cocina","multiple":true},{"enonce":"Complète avec le participe.","aide":"Avec *haber*, le participe ne s’accorde pas.","type":"trous","segments":["Las cartas que he ",0," son largas."],"banque":["escritos","escrito","escribido","escrita"]},{"enonce":"Pourquoi dit-on « las tazas están puestas » ?","aide":"Le fait est accompli : on décrit le résultat.","type":"choix","options":[{"id":"a","texte":"Puestas est invariable"},{"id":"b","texte":"Estar + participe donne un état, et il s’accorde"},{"id":"c","texte":"Les tasses sont le sujet de haber"},{"id":"d","texte":"Estar + participe donne une action en cours"}],"multiple":false},{"enonce":"Associe chaque infinitif à son participe.","aide":"Ce sont tous des participes irréguliers.","type":"association","gauche":[{"id":"g0","texte":"escribir"},{"id":"g1","texte":"volver"},{"id":"g2","texte":"romper"},{"id":"g3","texte":"satisfacer"}],"droite":[{"id":"d0","texte":"satisfecho"},{"id":"d1","texte":"vuelto"},{"id":"d2","texte":"escrito"},{"id":"d3","texte":"roto"}]}]}$ex$::jsonb,
