   $ex${"titre":"Les étés de grand-père Manuel","competence":"manier-langue","situation":"Álex interroge son grand-père sur les étés de son enfance. Le grand-père répond par messages.","documents":[{"id":"abuelo","type":"dialogue","modele":"sms","titre":"Álex et son abuelo","participants":[{"nom":"Álex","emoji":"👦","cote":"gauche"},{"nom":"Manuel","emoji":"👴","cote":"droite"}],"repliques":[{"qui":"Álex","texte":"Abuelo, ¿qué solías hacer en verano de pequeño?"},{"qui":"Manuel","texte":"Solía ir al río con mis hermanos. Y volví a ver ese río el año pasado."},{"qui":"Álex","texte":"¿Y tus hermanos?"},{"qui":"Manuel","texte":"Mi hermano mayor sigue viviendo en el pueblo."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux formes du verbe soler** dans la conversation.","aide":"Elles sont à l’imparfait de l’indicatif : l’une dans la question, l’autre dans la réponse.","type":"zone","document":"abuelo","multiple":true},{"enonce":"Que signifie « volví a ver ese río » ?","aide":"Volver a + infinitif répète une action ponctuelle.","type":"choix","options":[{"id":"a","texte":"J’ai l’habitude de voir cette rivière"},{"id":"b","texte":"Je voyais toujours cette rivière"},{"id":"c","texte":"Je continue à voir cette rivière"},{"id":"d","texte":"J’ai revu cette rivière"}],"multiple":false},{"enonce":"Complète avec la tournure qui dit que l’action **continue**.","aide":"Seguir + gérondif : l’action ne s’est pas arrêtée.","type":"trous","segments":["Mi hermano ",0," viviendo en el pueblo."],"banque":["vuelve","sigue","solía","suele"]},{"enonce":"Remets en ordre : « J’ai l’habitude de me lever à sept heures. » La phrase commence par Suelo.","aide":"Soler est suivi de l’infinitif, ici avec le pronom soudé.","type":"ordre","items":[{"id":"a","texte":"a"},{"id":"b","texte":"siete"},{"id":"c","texte":"las"},{"id":"d","texte":"levantarme"},{"id":"e","texte":"Suelo"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m8"]},"explication":"**Solías** et **solía** : soler à l’imparfait exprime l’habitude passée."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Volví a ver** : volver a + infinitif = refaire une action, ici « j’ai revu »."},{"cle":{"type":"trous","trous":[["sigue"]]},"affichage":"sigue","explication":"**Sigue viviendo** : seguir + gérondif exprime la continuation d’une action."},{"cle":{"type":"ordre","ids":["e","d","a","c","b"]},"explication":"**Suelo levantarme a las siete** : soler + infinitif, puis l’heure."}]$ex$::jsonb),
  ('9338c26a-fc25-51e5-8b85-9eeadb86162a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La routine d’Irene, nageuse","competence":"manier-langue","situation":"Irene, nageuse de quatorze ans, raconte sa semaine à un magazine de son collège. Un tableau résume ses habitudes.","documents":[{"id":"irene","type":"texte","genre":"article","titre":"Mi semana de nadadora","blocs":["Entrenamos de lunes a viernes. Normalmente me levanto a las seis, pero de vez en cuando me quedo en la cama.","Cuando era pequeña, solía nadar solo los sábados. Ahora sigo entrenando cada día y volví a participar en el campeonato el mes pasado."],"source":"Article écrit pour l’exercice"},{"id":"habitos","type":"tableau","titre":"Los hábitos de Irene","colonnes":["Hábito","Frecuencia"],"lignes":[["Entrenar","todos los días"],["Quedarse en la cama","de vez en cuando"],["Comer pasta antes de competir","siempre"],["Llegar tarde","casi nunca"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui dit l’**habitude dans le passé**.","aide":"C’est une forme de soler à l’imparfait.","type":"zone","document":"irene","multiple":false},{"enonce":"Que signifie « volví a participar en el campeonato » ?","aide":"Volver a + infinitif : on refait quelque chose une fois de plus.","type":"choix","options":[{"id":"a","texte":"Je ne participe plus au championnat"},{"id":"b","texte":"Je participais d’ordinaire au championnat"},{"id":"c","texte":"Je participe toujours au championnat"},{"id":"d","texte":"J’ai de nouveau participé au championnat"}],"multiple":false},{"enonce":"Dans le tableau, touche la fréquence de ce qu’Irene ne fait **presque jamais**.","aide":"Cherche la ligne sur le retard.","type":"zone","document":"habitos","multiple":false},{"enonce":"Associe chaque marqueur du tableau à son sens.","aide":"Todos los días embrasse l’ensemble des jours.","type":"association","gauche":[{"id":"g0","texte":"todos los días"},{"id":"g1","texte":"de vez en cuando"},{"id":"g2","texte":"siempre"},{"id":"g3","texte":"casi nunca"}],"droite":[{"id":"d0","texte":"toujours"},{"id":"d1","texte":"de temps en temps"},{"id":"d2","texte":"chaque jour, sans exception"},{"id":"d3","texte":"presque jamais"}]},{"enonce":"Les parents d’Irene ont l’habitude de dîner à neuf heures. Complète.","aide":"Le sujet est « mis padres » : 3e personne du pluriel.","type":"trous","segments":["Mis padres ",0," cenar a las nueve."],"banque":["suele","suelen","solemos","sueles"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24"]},"explication":"**Solía** : soler à l’imparfait = elle avait l’habitude de nager le samedi."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Volví a participar** : action ponctuelle répétée, « j’ai participé de nouveau »."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"**Casi nunca** : « presque jamais ». C’est la fréquence de la ligne « Llegar tarde »."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2","g3":"d3"}},"explication":"*Todos los días* = chaque jour ; *de vez en cuando* = de temps en temps ; *siempre* = toujours ; *casi nunca* = presque jamais."},{"cle":{"type":"trous","trous":[["suelen"]]},"affichage":"suelen","explication":"**Suelen cenar** : soler diphtongue (suelo, sueles, suele…, suelen) et se conjugue avec « mis padres »."}]$ex$::jsonb),
  ('426cc82e-eebb-500a-b233-a38e9b89c5a1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La liste de courses","competence":"lire-tableau","situation":"Inés fait les courses pour la famille. Sa liste est imprimée sur un ticket, et elle se méfie des genres : ils ne sont pas les mêmes qu’en français.","documents":[{"id":"ticket","type":"fiche","modele":"ticket","entete":"Supermercado Sol","sousTitre":"Lista de la compra","emoji":"🛒","lignes":[{"texte":"la leche","valeur":"1,20 €","id":"z1"},{"texte":"el queso","valeur":"3,50 €","id":"z2"},{"texte":"la sal","valeur":"0,80 €","id":"z3"},{"texte":"el pan","valeur":"1,10 €","id":"z4"},{"texte":"la miel","valeur":"4,00 €","id":"z5"}],"pied":"Gracias por su visita","teinte":"bleu","titre":"Ticket de caisse","source":"Ticket écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois produits** féminins en espagnol alors que le mot français est **masculin**.","aide":"Le lait, le sel et le miel : en français, ce sont des mots masculins.","type":"zone","document":"ticket","multiple":true},{"enonce":"Inés prend un crayon, puis deux autres : elle en a trois. Complète.","aide":"Les noms en -z font leur pluriel en -ces.","type":"trous","segments":["Hay un lápiz y dos más: tengo tres ",0,"."],"banque":["lápiz","lápizs","lápizes","lápices"]},{"enonce":"Range chaque nom selon son article.","aide":"Les terminaisons -ción et -dad sont féminines ; -aje et -or sont masculines.","type":"categories","categories":[{"id":"c0","texte":"la (féminin)"},{"id":"c1","texte":"el (masculin)"}],"items":[{"id":"i0","texte":"viaje"},{"id":"i1","texte":"color"},{"id":"i2","texte":"amor"},{"id":"i3","texte":"ciudad"},{"id":"i4","texte":"canción"},{"id":"i5","texte":"libertad"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z3","z5"]},"explication":"**la leche, la sal, la miel** : ces noms sont féminins en espagnol alors que « lait, sel, miel » sont masculins en français. On les apprend avec leur article."},{"cle":{"type":"trous","trous":[["lapices"]]},"affichage":"lápices","explication":"**lápices** : le -z devient -c devant -es (lápiz → lápices)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c0"}},"explication":"**-ción, -dad, -tad** → féminin ; **-aje, -or** → masculin."}]$ex$::jsonb),
  ('426cc82e-eebb-500a-b233-a38e9b89c5a1'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le pluriel en un coup d’œil","competence":"manier-langue","situation":"La professeure d’espagnol affiche un tableau à compléter : le pluriel ne se forme pas toujours avec un simple -s.","documents":[{"id":"plural","type":"tableau","titre":"Singular y plural","colonnes":["Singular","Plural"],"lignes":[["el papel","?"],["la canción","?"],["el examen","?"],["la vez","?"],["el lunes","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Complète le tableau avec la bonne forme du pluriel.","aide":"Après une consonne : -es ; -z devient -ces ; un mot en -s non accentué sur la dernière syllabe ne change pas.","type":"trous","segments":["el papel → los ",0," ; la canción → las ",1," ; el examen → los ",2," ; la vez → las ",3," ; el lunes → los ",4],"banque":["papeles","cancións","papels","exámenes","lunes","examenes","canciones","vezes","veces"]},{"enonce":"Parmi ces noms du tableau, lequel gagne un accent écrit au pluriel ?","aide":"L’accent suit la prononciation : où tombe l’accent tonique ?","type":"choix","options":[{"id":"a","texte":"la canción"},{"id":"b","texte":"el papel"},{"id":"c","texte":"la vez"},{"id":"d","texte":"el examen"}],"multiple":false},{"enonce":"Associe chaque nom masculin à son féminin.","aide":"Certains noms ne changent pas : seul l’article varie.","type":"association","gauche":[{"id":"g0","texte":"el niño"},{"id":"g1","texte":"el profesor"},{"id":"g2","texte":"el francés"},{"id":"g3","texte":"el estudiante"}],"droite":[{"id":"d0","texte":"la francesa"},{"id":"d1","texte":"la estudiante"},{"id":"d2","texte":"la profesora"},{"id":"d3","texte":"la niña"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["papeles"],["canciones"],["examenes"],["veces"],["lunes"]]},"affichage":"papeles · canciones · exámenes · veces · lunes","explication":"**papeles, canciones, exámenes, veces, lunes** : -es après consonne, -z → -ces, et *lunes* est invariable."},{"cle":{"type":"choix","ids":["d"]},"explication":"**examen → exámenes** : l’accent apparaît pour garder la même prononciation. *canción* perd son accent (canciones)."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g1":"d2","g0":"d3"}},"explication":"On change -o en -a, on ajoute -a après -or ou -és, et *estudiante* est invariable."}]$ex$::jsonb),
  ('426cc82e-eebb-500a-b233-a38e9b89c5a1'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une carte postale de Grenade","competence":"analyser-document","situation":"Sofía est en voyage à Grenade. Elle écrit à son amie Elena, et le professeur en tire un tableau de pluriels.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Sofía","blocs":["Querida Elena:","Granada es preciosa. El clima es seco y no hay ningún problema con el idioma: todos hablan despacio.","Ayer visité el museo y vi un cuadro con mucha sangre. Luego comí pan con miel.","Un abrazo, Sofía"],"source":"Texte écrit pour l’exercice"},{"id":"plurales","type":"tableau","titre":"Pluriels à compléter","colonnes":["Singular","Plural"],"lignes":[["la crisis","?"],["el rubí","?"],["el jueves","?"],["la luz","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois noms masculins** terminés en -a dans la lettre.","aide":"Ce sont des mots d’origine grecque : el … ma.","type":"zone","document":"carta","multiple":true},{"enonce":"Quelle phrase de Sofía est correcte ?","aide":"Color est masculin, sangre est féminin.","type":"choix","options":[{"id":"a","texte":"El color de la sangre es rojo."},{"id":"b","texte":"El color de el sangre es rojo."},{"id":"c","texte":"La color del sangre es rojo."},{"id":"d","texte":"La color de la sangre es rojo."}],"multiple":false},{"enonce":"Complète les pluriels du tableau.","aide":"Voyelle accentuée : -es. Mot en -s non accentué sur la dernière syllabe : invariable. -z : -ces.","type":"trous","segments":["la crisis → las ",0," ; el rubí → los ",1," ; el jueves → los ",2," ; la luz → las ",3],"banque":["luces","crisis","crises","jueves","rubís","rubíes","luzes"]},{"enonce":"Range chaque nom selon la formation de son pluriel.","aide":"Regarde la dernière lettre du mot.","type":"categories","categories":[{"id":"c0","texte":"+ s"},{"id":"c1","texte":"+ es"},{"id":"c2","texte":"z → ces"},{"id":"c3","texte":"Invariable"}],"items":[{"id":"i0","texte":"papel"},{"id":"i1","texte":"lápiz"},{"id":"i2","texte":"lunes"},{"id":"i3","texte":"casa"},{"id":"i4","texte":"crisis"},{"id":"i5","texte":"vez"},{"id":"i6","texte":"ciudad"},{"id":"i7","texte":"libro"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m13","m16"]},"explication":"**clima, problema, idioma** : les noms en -ma d’origine grecque sont masculins."},{"cle":{"type":"choix","ids":["a"]},"explication":"**El color de la sangre** : *el color* (masculin) et *la sangre* (féminin) ; *de el* ne s’écrit jamais."},{"cle":{"type":"trous","trous":[["crisis"],["rubies"],["jueves"],["luces"]]},"affichage":"crisis · rubíes · jueves · luces","explication":"**crisis** et **jueves** sont invariables ; **rubíes** (voyelle accentuée + -es) ; **luces** (-z → -ces)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c3","i3":"c0","i4":"c3","i5":"c2","i6":"c1","i7":"c0"}},"explication":"Voyelle → **-s** ; consonne → **-es** ; **-z → -ces** ; -s non accentué sur la dernière syllabe → **invariable**."}]$ex$::jsonb),
  ('5351a5a7-be71-5111-9952-d4261f8296db'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le courriel de Marta à son correspondant","competence":"comprendre-langue","situation":"Marta écrit à Pablo, son correspondant français. Elle lui parle de sa journée, de la veille et de son enfance.","documents":[{"id":"correo","type":"texte","genre":"lettre","titre":"Correo de Marta","blocs":["Hola, Pablo:","Hoy he escrito mi primer correo en francés. Ayer comí en casa de mi abuela y por la tarde vimos una película.","Cuando era pequeña, mi abuela cocinaba paella todos los domingos."],"source":"Courriel écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui forment le *pretérito perfecto* dans le courriel.","aide":"Il se compose de haber au présent et d’un participe passé ; le marqueur « Hoy » l’appelle.","type":"zone","document":"correo","multiple":true},{"enonce":"Touche les **deux verbes à l’indefinido** : des actions achevées, coupées du présent.","aide":"Cherche les actions de la veille, introduites par le marqueur « Ayer ».","type":"zone","document":"correo","multiple":true},{"enonce":"Marta dit ce que faisait sa grand-mère chaque dimanche. Complète.","aide":"Une habitude du passé appelle l’imperfecto ; regarde aussi la personne du verbe.","type":"trous","segments":["Todos los domingos mi abuela ",0," paella."],"banque":["cocinaba","ha cocinado","cocinaban","cocinó"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m4"]},"explication":"**he escrito** : *haber* au présent + participe passé. Le perfecto relie l’action à aujourd’hui (« Hoy… »)."},{"cle":{"type":"zone","ids":["m11","m21"]},"explication":"**comí** et **vimos** sont à l’indefinido : *ayer* coupe l’action du présent, l’action est achevée."},{"cle":{"type":"trous","trous":[["cocinaba"]]},"affichage":"cocinaba","explication":"**cocinaba** : une habitude (« todos los domingos ») se met à l’imperfecto, ici à la 3e personne du singulier (-aba)."}]$ex$::jsonb),
  ('5351a5a7-be71-5111-9952-d4261f8296db'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Messages après une soirée sous la pluie","competence":"manier-langue","situation":"Lucas et Irene s’écrivent le lendemain d’une journée pluvieuse. À toi de choisir le bon passé dans chaque phrase.","documents":[{"id":"chat","type":"dialogue","modele":"sms","titre":"Messages d’Irene et de Lucas","participants":[{"nom":"Irene","emoji":"👧","cote":"gauche"},{"nom":"Lucas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Irene","texte":"Lucas, ¿qué hiciste ayer?"},{"qui":"Lucas","texte":"Ayer fui a casa de Sara. Llovía mucho cuando salí de casa."},{"qui":"Irene","texte":"Yo me quedé en casa. Hoy he llegado tarde a clase."},{"qui":"Lucas","texte":"Mi abuelo siempre decía que la lluvia trae suerte."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes à l’imperfecto** : l’un plante un décor, l’autre dit une habitude.","aide":"Un verbe suit « siempre », l’autre dit ce qui durait quand Lucas est sorti.","type":"zone","document":"chat","multiple":true},{"enonce":"Touche le **marqueur de temps** qui appelle le *pretérito perfecto* (« he llegado »).","aide":"C’est un mot qui dit que le moment n’est pas encore fini.","type":"zone","document":"chat","multiple":false},{"enonce":"Associe chaque marqueur au temps qu’il appelle.","aide":"Pense à l’action achevée, au passé relié à aujourd’hui et à l’habitude.","type":"association","gauche":[{"id":"g0","texte":"ayer"},{"id":"g1","texte":"hoy"},{"id":"g2","texte":"siempre"}],"droite":[{"id":"d0","texte":"perfecto"},{"id":"d1","texte":"indefinido"},{"id":"d2","texte":"imperfecto"}]},{"enonce":"Complète avec la forme qui convient (nosotros, une action achevée la veille).","aide":"Ayer coupe du présent ; la personne est nosotros.","type":"trous","segments":["Ayer nosotros ",0," paella en casa de Sara."],"banque":["comieron","hemos comido","comemos","comimos"]},{"enonce":"Remets en ordre : « Il dormait quand le téléphone a sonné. » La phrase commence par Dormía.","aide":"L’imperfecto plante le décor, l’indefinido l’interrompt.","type":"ordre","items":[{"id":"a","texte":"el teléfono"},{"id":"b","texte":"cuando"},{"id":"c","texte":"Dormía"},{"id":"d","texte":"sonó"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10","m30"]},"explication":"**Llovía** (le décor) et **decía** (l’habitude : « siempre ») sont à l’imperfecto ; *fui*, *salí* et *me quedé* sont des actions achevées."},{"cle":{"type":"zone","ids":["m21"]},"explication":"**Hoy** : la journée n’est pas finie, le passé reste relié au présent, donc *he llegado*."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"*Ayer* → **indefinido** (achevé), *hoy* → **perfecto** (relié au présent), *siempre* → **imperfecto** (habitude)."},{"cle":{"type":"trous","trous":[["comimos"]]},"affichage":"comimos","explication":"**comimos** : indefinido de *comer* à nosotros (-imos). *Hemos comido* serait fautif avec *ayer*."},{"cle":{"type":"ordre","ids":["c","b","d","a"]},"explication":"**Dormía cuando sonó el teléfono** : le décor à l’imperfecto, l’événement qui survient à l’indefinido."}]$ex$::jsonb),
  ('5351a5a7-be71-5111-9952-d4261f8296db'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une nuit d’été à Séville","competence":"analyser-texte","situation":"Un récit de voyage mêle décor et événements. Une fiche de correction relève quatre phrases, dont une est fausse.","documents":[{"id":"noche","type":"texte","genre":"recit","titre":"Una noche en Sevilla","blocs":["Era una noche de verano en Sevilla. Hacía calor y la gente paseaba por la plaza.","De pronto, un músico empezó a cantar y todos se callaron. Cuando terminó, los turistas aplaudieron."],"source":"Texte écrit pour l’exercice"},{"id":"fichas","type":"tableau","titre":"Cuatro frases del cuaderno","colonnes":["Frase del alumno"],"lignes":[["Hoy he estudiado mucho."],["El año pasado viajé a Cuba."],["Ayer he comido paella."],["Esta semana he trabajado mucho."]],"enteteLignes":false,"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes qui plantent le décor** (imperfecto).","aide":"Ils disent ce qui durait : la nuit, la chaleur, les promenades.","type":"zone","document":"noche","multiple":true},{"enonce":"Touche les **quatre verbes qui font avancer l’action** (indefinido).","aide":"Ce sont des événements qui surviennent, chacun achevé.","type":"zone","document":"noche","multiple":true},{"enonce":"Dans le tableau, une phrase est **fautive**. Touche-la.","aide":"Regarde le marqueur de temps : est-il coupé du présent ou relié à lui ?","type":"zone","document":"fichas","multiple":false},{"enonce":"Pourquoi « Ayer he comido paella » est-elle fautive ?","aide":"Compare avec « Hoy he estudiado mucho » : qu’est-ce qui change ?","type":"choix","options":[{"id":"a","texte":"Le perfecto est réservé aux verbes en -ar, pas en -er"},{"id":"b","texte":"Avec ayer, l’espagnol exige toujours l’imparfait pour manger"},{"id":"c","texte":"Le mot paella impose le pretérito imperfecto dans ce cas"},{"id":"d","texte":"Ayer situe l’action hors du présent : il faut l’indefinido"}],"multiple":false},{"enonce":"Associe chaque verbe (personne et temps indiqués) à sa forme.","aide":"L’imparfait n’a que trois irréguliers : ser, ir, ver.","type":"association","gauche":[{"id":"g0","texte":"comer (él, indefinido)"},{"id":"g1","texte":"hablar (ellos, indefinido)"},{"id":"g2","texte":"vivir (nosotros, imparfait)"},{"id":"g3","texte":"ir (yo, imparfait)"}],"droite":[{"id":"d0","texte":"iba"},{"id":"d1","texte":"hablaron"},{"id":"d2","texte":"comió"},{"id":"d3","texte":"vivíamos"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m7","m12"]},"explication":"**Era, Hacía, paseaba** : l’imperfecto décrit le décor et ce qui durait."},{"cle":{"type":"zone","ids":["m20","m26","m28","m31"]},"explication":"**empezó, callaron, terminó, aplaudieron** : chaque événement rompt le décor, l’action avance."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"**Ayer he comido paella** est fautive : *ayer* coupe du présent, il faut *Ayer comí paella*."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Ayer coupe l’action du présent** : on emploie l’indefinido (*comí*). Le perfecto est réservé à ce qui touche encore à aujourd’hui."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"*comió* (-ió), *hablaron* (-aron), *vivíamos* (-íamos), *iba* (ir est un des trois irréguliers de l’imparfait)."}]$ex$::jsonb),
  ('fdcb68fb-2c2e-568d-9929-e0a7e2b865d4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui nettoie le tableau ?","competence":"comprendre-langue","situation":"Dans la classe d’Álex, la professeure fait des annonces par message. Les virgules changent tout.","documents":[{"id":"clase","type":"dialogue","modele":"sms","titre":"Groupe de classe","participants":[{"nom":"Profesora","emoji":"👩‍🏫","cote":"gauche"},{"nom":"Álex","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Profesora","texte":"Los alumnos que llegan tarde limpian la pizarra."},{"qui":"Álex","texte":"Yo llego tarde a veces. ¿Y mis compañeros?"},{"qui":"Profesora","texte":"Tus compañeros, que llegan temprano, ganan un punto."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Qui doit nettoyer le tableau ?","aide":"La première relative n’a pas de virgules.","type":"choix","options":[{"id":"a","texte":"Personne"},{"id":"b","texte":"Tous les élèves de la classe"},{"id":"c","texte":"Seulement les élèves qui arrivent en retard"},{"id":"d","texte":"Seulement les élèves qui arrivent à l’heure"}],"multiple":false},{"enonce":"Touche le « que » de la relative **explicative** (celle qui est entre virgules).","aide":"C’est dans le dernier message de la professeure.","type":"zone","document":"clase","multiple":false},{"enonce":"Remets en ordre : « La maison dans laquelle je vis. » La phrase commence par La.","aide":"La préposition précède toujours le relatif.","type":"ordre","items":[{"id":"a","texte":"en la que"},{"id":"b","texte":"casa"},{"id":"c","texte":"La"},{"id":"d","texte":"vivo"}]}]}$ex$::jsonb,
